@Mixin(GameRenderer.class)
public abstract class GameRendererMixin {

    @org.spongepowered.asm.mixin.injection.ModifyArgs(method = "renderLevel", at = @At(value = "INVOKE", target = "Lnet/minecraft/client/renderer/LevelRenderer;renderLevel(Lcom/mojang/blaze3d/resource/GraphicsResourceAllocator;Lnet/minecraft/client/DeltaTracker;ZLnet/minecraft/client/Camera;Lorg/joml/Matrix4f;Lorg/joml/Matrix4f;Lorg/joml/Matrix4f;Lcom/mojang/blaze3d/buffers/GpuBufferSlice;Lorg/joml/Vector4f;Z)V"))
    private void godwand$captureWorld(org.spongepowered.asm.mixin.injection.invoke.arg.Args args) {
        var timer = (net.minecraft.client.DeltaTracker)args.get(1);
        org.joml.Matrix4f view=args.get(4), projection=args.get(5);
        float delta=timer.getGameTimeDeltaPartialTick(false);
        net.godwand.client.GodWandPostFxManager.onWorldRender(view, projection, delta);
        net.godwand.client.AtomicPostFx.capture(view, projection, delta);
        // Fabric only queues the procedural geometry during the level; draw it now, before the composite.
        net.godwand.client.compat.GodWandGeometry.flushDeferred();
    }


    @Inject(method = "renderLevel", at = @At(value = "FIELD", target =
            "Lnet/minecraft/client/renderer/GameRenderer;hud3dProjectionMatrixBuffer:Lnet/minecraft/client/renderer/CachedPerspectiveProjectionMatrixBuffer;"))
    private void godwand$afterWorldComposite(CallbackInfo ci) {
        net.godwand.client.GodWandPostFxManager.renderAfterWorld();
        net.godwand.client.AtomicPostFx.renderAfterWorld();

